package io.knowledgebrain.learning;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.flywaydb.core.Flyway;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;import io.knowledgebrain.contracts.learning.courseprogress.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_DATABASE_URL",matches=".+")
class CourseProgressStoreIntegrationTest {
 PGSimpleDataSource source;JdbcTemplate sql;CourseProgressStore store;UuidV7 ids=new UuidV7(Clock.systemUTC());CourseContextClient.Reference ref;String trace="a".repeat(32);
 @BeforeEach void setup(){source=new PGSimpleDataSource();source.setURL(System.getenv("BRAIN_TEST_LEARNING_DATABASE_URL"));source.setUser("brain_learning");source.setPassword(System.getenv("BRAIN_TEST_LEARNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(source).load().migrate();sql=new JdbcTemplate(source);store=new CourseProgressStore(source,Clock.systemUTC());ref=new CourseContextClient.Reference(ids.next(),ids.next(),ids.next(),ids.next(),3,"ACTIVE","MEMBER",ids.next(),1,"ENROLLED",List.of(new CourseContextClient.Study(ids.next(),1,"First"),new CourseContextClient.Study(ids.next(),2,"Second")));}
 CourseContextClient.Reference context(UUID actor,String role,String state,String enrollment,long enrollmentVersion,long courseVersion){return new CourseContextClient.Reference(actor,ref.groupId(),ref.spaceId(),ref.courseId(),courseVersion,state,role,ref.enrollmentId(),enrollmentVersion,enrollment,ref.studies());}
 CourseProgressStore.Progress change(long expected,int step,String state){return store.change(ref,ref.studies().get(step).studyId(),expected,state,trace);}
 int events(UUID id){return sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid=?",Integer.class,id);}
 void status(int code,org.junit.jupiter.api.function.Executable action){assertEquals(code,assertThrows(ResponseStatusException.class,action).getStatusCode().value());}
 @Test void readAndInitialNotStartedNoOpAllocateNoPersistentProgress(){var empty=store.get(ref);assertNull(empty.progressId());assertEquals(0,empty.version());assertTrue(empty.steps().stream().allMatch(s->s.status().equals("NOT_STARTED")));assertEquals(empty,change(0,0,"NOT_STARTED"));assertTrue(store.history(ref,Long.MAX_VALUE,5).items().isEmpty());assertEquals(0,sql.queryForObject("SELECT count(*) FROM group_course_progress WHERE course_id=?",Integer.class,ref.courseId()));}
 @Test void fullSnapshotRevisionAndEventCommitTogetherWithPrivateProvenance()throws Exception{var v=change(0,0,"IN_PROGRESS");assertEquals(7,v.progressId().version());assertEquals("PRIVATE",v.visibility());assertEquals("PARTICIPANT_ONLY",v.audience());assertEquals(ref.principalId(),v.participantId());assertEquals(3,v.courseVersion());assertEquals(ref.enrollmentId(),v.enrollmentId());assertEquals(1,v.enrollmentVersion());assertEquals(v,store.history(ref,Long.MAX_VALUE,5).items().getFirst().snapshot());var e=CourseProgressEnvelopeV1.parseFrom(sql.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.progressId()));var p=CourseProgressSnapshotV1.parseFrom(e.getPayload());assertEquals(trace,e.getTraceId());assertEquals(ref.spaceId().toString(),e.getSpaceId());assertEquals(ref.principalId().toString(),e.getActorId());assertEquals("CourseProgress",e.getAggregateType());assertEquals("PARTICIPANT_ONLY",p.getAudience());assertEquals(2,p.getStepsCount());assertEquals("IN_PROGRESS",p.getSteps(0).getStatus());assertEquals("NOT_STARTED",p.getSteps(1).getStatus());assertEquals(1,p.getVersion());}
 @Test void progressIsIsolatedByAuthenticatedParticipantEvenForGroupOwner(){var v=change(0,0,"COMPLETED");var owner=context(ids.next(),"OWNER","ACTIVE","ENROLLED",1,3);assertNull(store.get(owner).progressId());assertTrue(store.history(owner,Long.MAX_VALUE,5).items().isEmpty());var own=store.change(owner,ref.studies().getFirst().studyId(),0,"IN_PROGRESS",trace);assertNotEquals(v.progressId(),own.progressId());assertEquals("COMPLETED",store.get(ref).steps().getFirst().status());assertEquals("IN_PROGRESS",store.get(owner).steps().getFirst().status());}
 @Test void staleWritesNoOpsAndExplicitCorrectionsKeepOneIdentity(){var v=change(0,0,"COMPLETED");assertEquals(v,change(1,0,"COMPLETED"));status(412,()->change(0,0,"COMPLETED"));assertEquals(1,events(v.progressId()));var corrected=change(1,0,"IN_PROGRESS");assertEquals(v.progressId(),corrected.progressId());assertEquals(v,new CourseProgressStore(source,Clock.systemUTC()).history(ref,2,5).items().getFirst().snapshot());var reset=change(2,0,"NOT_STARTED");assertEquals(v.progressId(),reset.progressId());assertEquals(3,events(v.progressId()));}
 @Test void withdrawnViewerRetiredAndForeignStudiesFailWithoutMutating(){var v=change(0,0,"IN_PROGRESS");for(var denied:List.of(context(ref.principalId(),"VIEWER","ACTIVE","ENROLLED",1,3),context(ref.principalId(),"MEMBER","ACTIVE","WITHDRAWN",2,3),context(ref.principalId(),"MEMBER","RETIRED","ENROLLED",1,4)))status(409,()->store.change(denied,ref.studies().getFirst().studyId(),1,"COMPLETED",trace));status(404,()->store.change(ref,ids.next(),1,"COMPLETED",trace));status(400,()->change(1,0,"PASSED"));assertEquals(v,store.get(ref));assertEquals(v,store.get(context(ref.principalId(),"VIEWER","RETIRED","WITHDRAWN",2,4)));var done=context(ref.principalId(),"MEMBER","COMPLETED","ENROLLED",1,4);assertEquals("COMPLETED",store.change(done,ref.studies().getFirst().studyId(),1,"COMPLETED",trace).steps().getFirst().status());}
 @Test void reEnrollmentPreservesProgressAndPinsNewObservedVersions(){var v=change(0,0,"COMPLETED");var again=context(ref.principalId(),"MEMBER","ACTIVE","ENROLLED",3,4);var next=store.change(again,ref.studies().get(1).studyId(),1,"COMPLETED",trace);assertEquals(v.progressId(),next.progressId());assertEquals(3,next.enrollmentVersion());assertEquals(4,next.courseVersion());assertTrue(next.steps().stream().allMatch(s->s.status().equals("COMPLETED")));assertEquals(1,store.history(ref,2,5).items().getFirst().snapshot().enrollmentVersion());}
 @Test void historyUsesDescendingIndependentProgressCursor(){change(0,0,"IN_PROGRESS");change(1,0,"COMPLETED");change(2,1,"IN_PROGRESS");var h=store.history(ref,Long.MAX_VALUE,2);assertEquals(List.of(3L,2L),h.items().stream().map(CourseProgressStore.Revision::version).toList());assertEquals(1,store.history(ref,h.nextBefore(),2).items().size());}
 @Test void concurrentInitialAndExistingWritesHaveOneWinnerWithoutLostStep()throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);for(int round=0;round<2;round++){long expected=round;var result=new ArrayList<Future<Boolean>>();for(int step=0;step<2;step++){int index=step;String target=round==0?"IN_PROGRESS":"COMPLETED";result.add(pool.submit(()->{barrier.await();try{change(expected,index,target);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));}assertNotEquals(result.get(0).get(),result.get(1).get());assertEquals(round+1,store.get(ref).version());}assertEquals(2,events(store.get(ref).progressId()));}}
 @Test void outboxFailureRollsBackInitialAndChangedSnapshotAudit(){String name="course_progress_fail_"+ref.courseId().toString().replace("-","");String check=" CHECK(aggregatetype<>'course-progress' OR trace_id<>'"+trace+"') NOT VALID";sql.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+check);try{assertThrows(RuntimeException.class,()->change(0,0,"IN_PROGRESS"));assertNull(store.get(ref).progressId());assertTrue(store.history(ref,Long.MAX_VALUE,5).items().isEmpty());}finally{sql.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}var v=change(0,0,"IN_PROGRESS");sql.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+check);try{assertThrows(RuntimeException.class,()->change(1,0,"COMPLETED"));assertEquals(v,store.get(ref));assertEquals(1,events(v.progressId()));assertEquals(1,store.history(ref,Long.MAX_VALUE,5).items().size());}finally{sql.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}}
 @Test void maximumCurriculumAndChangedExternalLayoutAreChecked(){var studies=new ArrayList<CourseContextClient.Study>();for(int n=0;n<50;n++)studies.add(new CourseContextClient.Study(ids.next(),1,"Study "+n));var max=new CourseContextClient.Reference(ref.principalId(),ref.groupId(),ref.spaceId(),ref.courseId(),3,"ACTIVE","MEMBER",ref.enrollmentId(),1,"ENROLLED",List.copyOf(studies));var v=store.change(max,studies.getLast().studyId(),0,"COMPLETED",trace);assertEquals(50,v.steps().size());status(409,()->store.get(ref));studies.add(new CourseContextClient.Study(ids.next(),1,"Too many"));var over=new CourseContextClient.Reference(ref.principalId(),ref.groupId(),ref.spaceId(),ref.courseId(),3,"ACTIVE","MEMBER",ref.enrollmentId(),1,"ENROLLED",List.copyOf(studies));status(503,()->store.change(over,studies.getFirst().studyId(),1,"COMPLETED",trace));}
}
